        $balita = [
            ['Nasi Ikan Gabus Kuah Kelor', 'nasi-ikan-gabus-kuah-kelor', 'Nasi dengan ikan gabus kuah bening daun kelor, menu anti-stunting kaya albumin dan kalsium.', '1-3 tahun', 3, ['Beras Putih' => 80, 'Ikan Gabus' => 50, 'Daun Kelor' => 20, 'Tahu' => 20], "1. Masak nasi putih seperti biasa\n2. Bersihkan ikan gabus, potong sesuai porsi anak\n3. Rebus ikan gabus dalam air hingga matang, sisihkan\n4. Petik daun kelor, cuci bersih\n5. Masukkan daun kelor ke kaldu ikan, masak 3 menit\n6. Potong tahu dadu kecil, goreng sebentar\n7. Tata nasi di piring, sajikan ikan gabus, tahu, dan kuah kelor\n8. Pastikan duri ikan sudah dibuang sebelum disajikan", 3],
            ['Sup Ayam Sayur Kampung', 'sup-ayam-sayur-kampung', 'Sup ayam kampung dengan aneka sayur pekarangan, hangat bergizi untuk balita.', '1-3 tahun', 3, ['Daging Ayam' => 50, 'Wortel' => 25, 'Kentang' => 40, 'Bayam' => 20], "1. Rebus ayam kampung dengan air secukupnya hingga empuk\n2. Angkat ayam, suwir dagingnya kecil-kecil\n3. Kupas kentang dan wortel, potong dadu kecil\n4. Masukkan kentang dan wortel ke kaldu ayam, rebus 10 menit\n5. Petik bayam, masukkan terakhir, masak 2 menit\n6. Masukkan kembali ayam suwir\n7. Beri sedikit garam, sajikan hangat dengan nasi", 3],
            ['Nasi Uduk Ikan Teri Tempe', 'nasi-uduk-ikan-teri-tempe-balita', 'Nasi uduk gurih dengan ikan teri goreng dan tempe orek, protein berlimpah.', '1-3 tahun', 3, ['Beras Putih' => 80, 'Santan' => 30, 'Ikan Teri' => 20, 'Tempe' => 30], "1. Cuci beras, masak dengan santan encer dan sedikit garam\n2. Cuci ikan teri, goreng dengan sedikit minyak hingga garing\n3. Potong tempe dadu kecil, goreng hingga keemasan\n4. Orek tempe goreng dengan sedikit kecap manis\n5. Tata nasi uduk di piring\n6. Sajikan dengan ikan teri goreng dan tempe orek", 3],
            ['Pepes Ikan Patin Daun Pisang', 'pepes-ikan-patin-daun-pisang', 'Pepes ikan patin bumbu kuning dibungkus daun pisang, lembut dan harum.', '1-3 tahun', 3, ['Ikan Patin' => 60, 'Beras Putih' => 80, 'Tomat' => 20], "1. Bersihkan ikan patin, lumuri dengan bumbu kunyit dan garam\n2. Iris tomat tipis-tipis\n3. Siapkan daun pisang, layukan di atas api sebentar\n4. Letakkan ikan di atas daun pisang, taburi irisan tomat\n5. Bungkus rapi, semat dengan lidi\n6. Kukus pepes 25 menit hingga matang dan harum\n7. Sajikan dengan nasi putih hangat", 3],
            ['Nasi Goreng Ikan Tongkol Sayur', 'nasi-goreng-ikan-tongkol-sayur', 'Nasi goreng dengan suwiran ikan tongkol dan sayuran segar, tanpa MSG.', '1-3 tahun', 3, ['Beras Putih' => 80, 'Ikan Tongkol' => 40, 'Kangkung' => 20, 'Telur Ayam' => 30], "1. Masak nasi, biarkan agak dingin\n2. Kukus ikan tongkol, suwir halus\n3. Kocok telur, buat orak-arik\n4. Petik kangkung, potong pendek\n5. Panaskan sedikit minyak, tumis kangkung sebentar\n6. Masukkan nasi, aduk rata dengan api besar\n7. Tambahkan ikan suwir dan telur orak-arik\n8. Aduk rata, sajikan hangat", 3],
            ['Sayur Asem Jagung Kacang Panjang', 'sayur-asem-jagung-kacang-panjang', 'Sayur asem segar khas Sunda dengan jagung dan kacang panjang, cocok pendamping lauk.', '1-3 tahun', 3, ['Jagung Manis' => 40, 'Kacang Panjang' => 30, 'Labu Siam' => 30], "1. Pipil jagung manis dari tongkolnya\n2. Potong kacang panjang sepanjang 2 cm\n3. Kupas labu siam, potong dadu\n4. Didihkan air, masukkan jagung terlebih dahulu\n5. Setelah 10 menit, tambahkan labu siam\n6. Masukkan kacang panjang, masak 5 menit lagi\n7. Tambahkan asam jawa sedikit dan garam\n8. Sajikan hangat sebagai pendamping lauk", 3],
            ['Telur Dadar Daun Kelor', 'telur-dadar-daun-kelor', 'Telur dadar tebal berisi daun kelor, cara praktis makan superfood untuk balita.', '1-3 tahun', 3, ['Telur Ayam' => 50, 'Daun Kelor' => 15, 'Beras Putih' => 80], "1. Petik daun kelor muda, cuci bersih, cincang halus\n2. Kocok telur dalam mangkuk\n3. Campurkan daun kelor cincang ke kocokan telur\n4. Tambahkan sedikit garam, aduk rata\n5. Panaskan wajan dengan sedikit minyak\n6. Tuang adonan, ratakan, masak api kecil\n7. Balik saat bagian bawah kecokelatan\n8. Masak hingga matang, potong kecil, sajikan dengan nasi", 3],
            ['Opor Ayam Labu Kuning', 'opor-ayam-labu-kuning', 'Opor ayam santan dengan labu kuning, gurih lembut dan kaya vitamin A.', '1-3 tahun', 3, ['Daging Ayam' => 50, 'Labu Kuning' => 40, 'Santan' => 40, 'Beras Putih' => 80], "1. Potong ayam sesuai porsi anak\n2. Kupas labu kuning, potong dadu\n3. Didihkan santan encer dengan bumbu opor\n4. Masukkan ayam, masak 20 menit hingga empuk\n5. Tambahkan labu kuning, masak 10 menit lagi\n6. Aduk perlahan agar labu tidak hancur\n7. Masak hingga kuah mengental\n8. Sajikan dengan nasi putih hangat", 3],
            ['Nasi Ikan Bandeng Presto Sayur', 'nasi-ikan-bandeng-presto-sayur', 'Nasi dengan bandeng presto dan tumis kangkung, tulang bandeng jadi sumber kalsium.', '1-3 tahun', 3, ['Beras Putih' => 80, 'Ikan Bandeng' => 50, 'Kangkung' => 25], "1. Masak nasi putih seperti biasa\n2. Presto ikan bandeng dengan panci presto 30 menit\n3. Goreng bandeng presto hingga keemasan\n4. Petik kangkung, potong batang mudanya\n5. Tumis kangkung dengan sedikit bawang putih\n6. Tata nasi, bandeng goreng, dan tumis kangkung di piring\n7. Tulang bandeng presto sudah lunak dan bisa dimakan anak", 3],
            ['Sop Daging Sapi Kentang Wortel', 'sop-daging-sapi-kentang-wortel', 'Sop daging sapi empuk dengan kentang dan wortel, klasik bergizi tinggi.', '1-3 tahun', 3, ['Daging Sapi' => 40, 'Kentang' => 40, 'Wortel' => 25, 'Beras Putih' => 80], "1. Rebus daging sapi dengan api kecil hingga empuk (45 menit)\n2. Potong daging kecil-kecil sesuai porsi anak\n3. Kupas kentang dan wortel, potong dadu\n4. Masukkan kentang dan wortel ke kaldu daging\n5. Masak hingga sayuran empuk (10 menit)\n6. Beri sedikit garam dan merica\n7. Sajikan sop hangat dengan nasi putih", 3],
            ['Oseng Tempe Kacang Panjang', 'oseng-tempe-kacang-panjang', 'Tumis tempe dan kacang panjang kecap, protein nabati dan serat tinggi.', '1-3 tahun', 3, ['Tempe' => 50, 'Kacang Panjang' => 30, 'Beras Putih' => 80], "1. Potong tempe tipis kotak-kotak kecil\n2. Goreng tempe sebentar hingga agak garing\n3. Potong kacang panjang sepanjang 2 cm\n4. Tumis bawang merah dan bawang putih iris\n5. Masukkan kacang panjang, tumis hingga layu\n6. Tambahkan tempe goreng dan kecap manis\n7. Aduk rata, tambahkan sedikit air, masak 3 menit\n8. Sajikan dengan nasi putih", 3],
            ['Gulai Ikan Nila Daun Singkong', 'gulai-ikan-nila-daun-singkong', 'Gulai ikan nila khas Padang dengan daun singkong, paduan protein dan kalsium.', '1-3 tahun', 3, ['Ikan Nila' => 50, 'Daun Singkong' => 30, 'Santan' => 40, 'Beras Putih' => 80], "1. Bersihkan ikan nila, potong sesuai porsi\n2. Petik daun singkong muda, remas dengan garam agar empuk\n3. Rebus daun singkong 15 menit, tiriskan\n4. Didihkan santan dengan bumbu gulai\n5. Masukkan ikan nila, masak 15 menit\n6. Tambahkan daun singkong, masak 5 menit lagi\n7. Sajikan gulai hangat dengan nasi", 3],
            ['Perkedel Ikan Mas Kentang', 'perkedel-ikan-mas-kentang', 'Perkedel ikan mas dan kentang goreng, lembut dan disukai anak.', '1-3 tahun', 3, ['Ikan Mas' => 40, 'Kentang' => 60, 'Telur Ayam' => 30], "1. Kukus ikan mas hingga matang, pisahkan daging dari tulang\n2. Rebus kentang hingga empuk, haluskan dengan garpu\n3. Campurkan daging ikan dan kentang halus\n4. Kocok telur, gunakan sebagian untuk campuran adonan\n5. Bentuk adonan bulat pipih kecil\n6. Celupkan ke sisa kocokan telur\n7. Goreng dengan minyak secukupnya hingga keemasan\n8. Tiriskan, sajikan hangat", 3],
            ['Sup Tahu Telur Sayuran', 'sup-tahu-telur-sayuran', 'Sup bening tahu dan telur dengan aneka sayur, ringan dan kaya protein.', '1-3 tahun', 3, ['Tahu' => 40, 'Telur Ayam' => 30, 'Wortel' => 20, 'Bayam' => 15], "1. Potong tahu dadu kecil\n2. Rebus telur hingga matang, belah empat\n3. Kupas dan potong wortel tipis\n4. Didihkan air, masukkan wortel, masak 5 menit\n5. Tambahkan tahu, masak 3 menit\n6. Petik bayam, masukkan terakhir, masak 2 menit\n7. Beri sedikit garam dan merica\n8. Sajikan sup hangat dengan nasi, tambahkan telur", 3],
            ['Nasi Tim Hati Sapi Wortel', 'nasi-tim-hati-sapi-wortel', 'Nasi tim hati sapi dan wortel, sumber zat besi tertinggi untuk cegah anemia.', '1-3 tahun', 3, ['Beras Putih' => 80, 'Hati Sapi' => 30, 'Wortel' => 20], "1. Masak beras menjadi nasi agak lembek\n2. Rendam hati sapi di air jeruk nipis 10 menit\n3. Rebus hati sapi hingga matang, potong dadu kecil\n4. Kupas wortel, parut kasar\n5. Campurkan nasi, hati sapi, dan wortel\n6. Tim dalam panci kukusan 15 menit\n7. Aduk rata, sajikan hangat\n8. Bisa ditambahkan sedikit kecap manis", 3],
        ];

        foreach ($balita as $r) { $makeRecipe($r); }

