        $anak = [
            ['Nasi Pecel Lele Lalapan', 'nasi-pecel-lele-lalapan', 'Nasi dengan lele goreng dan lalapan segar plus sambal, favorit anak Indonesia.', '4-6 tahun', 4, ['Beras Putih' => 120, 'Ikan Lele' => 80, 'Kangkung' => 30, 'Tomat' => 20], "1. Masak nasi putih\n2. Bersihkan ikan lele, lumuri garam dan kunyit\n3. Goreng lele dengan minyak panas hingga garing\n4. Rebus kangkung sebentar untuk lalapan, tiriskan\n5. Iris tomat segar sebagai pelengkap\n6. Tata nasi, lele goreng, dan lalapan di piring\n7. Sajikan dengan sambal ringan untuk anak", 3],
            ['Gado-Gado Sayur Lokal', 'gado-gado-sayur-lokal', 'Gado-gado sayuran lokal dengan bumbu kacang, protein nabati dan serat berlimpah.', '4-6 tahun', 4, ['Kacang Tanah' => 40, 'Kangkung' => 30, 'Tahu' => 40, 'Tempe' => 30, 'Kecambah/Tauge' => 20, 'Telur Ayam' => 50], "1. Rebus kangkung dan tauge sebentar, tiriskan\n2. Goreng tahu dan tempe hingga keemasan\n3. Rebus telur, kupas, belah dua\n4. Goreng kacang tanah, tumbuk halus\n5. Campurkan kacang tumbuk dengan air, gula, garam jadi saus\n6. Tata sayuran, tahu, tempe, telur di piring\n7. Siram dengan saus kacang\n8. Sajikan sebagai makan siang", 3],
            ['Nasi Liwet Ikan Teri Labu', 'nasi-liwet-ikan-teri-labu', 'Nasi liwet gurih khas Solo dengan ikan teri dan labu siam, komplit dan lezat.', '4-6 tahun', 4, ['Beras Putih' => 120, 'Santan' => 40, 'Ikan Teri' => 25, 'Labu Siam' => 30], "1. Cuci beras, masak dengan santan, daun salam, dan garam\n2. Goreng ikan teri dengan sedikit minyak hingga garing\n3. Kupas labu siam, potong korek api\n4. Tumis labu siam hingga layu dan matang\n5. Setelah nasi liwet matang, aduk perlahan\n6. Tata nasi liwet di piring, taburi ikan teri goreng\n7. Sajikan dengan tumis labu siam", 3],
            ['Rawon Daging Sapi Tauge', 'rawon-daging-sapi-tauge', 'Rawon daging sapi khas Jawa Timur dengan tauge segar, berkuah hitam bergizi.', '4-6 tahun', 4, ['Daging Sapi' => 60, 'Kecambah/Tauge' => 25, 'Beras Putih' => 120, 'Telur Ayam' => 50], "1. Rebus daging sapi dengan bumbu rawon hingga empuk\n2. Potong daging kecil-kecil\n3. Rebus telur, kupas, goreng sebentar\n4. Cuci tauge, seduh dengan air panas, tiriskan\n5. Masak nasi putih\n6. Tata nasi di mangkuk, siram kuah rawon\n7. Tambahkan daging, telur, dan tauge\n8. Sajikan hangat", 3],
            ['Ayam Goreng Bumbu Kuning Sayur', 'ayam-goreng-bumbu-kuning-sayur', 'Ayam goreng bumbu kuning kunyit dengan sayur bening bayam jagung.', '4-6 tahun', 4, ['Daging Ayam' => 80, 'Bayam' => 30, 'Jagung Manis' => 30, 'Beras Putih' => 120], "1. Lumuri ayam dengan bumbu kuning (kunyit, garam, bawang putih)\n2. Ungkep ayam dengan sedikit air hingga bumbu meresap\n3. Goreng ayam ungkep hingga keemasan dan garing\n4. Pipil jagung, rebus dalam air mendidih\n5. Tambahkan bayam, masak 2 menit saja\n6. Beri garam secukupnya\n7. Sajikan ayam goreng dengan sayur bening dan nasi", 3],
            ['Pindang Ikan Patin Nangka', 'pindang-ikan-patin-nangka', 'Pindang ikan patin khas Palembang dengan nangka muda, masakan tradisional bergizi.', '4-6 tahun', 4, ['Ikan Patin' => 80, 'Nangka Muda' => 40, 'Beras Putih' => 120, 'Tomat' => 20], "1. Bersihkan ikan patin, potong per porsi\n2. Kupas nangka muda, potong dadu, rendam air garam\n3. Rebus nangka muda 15 menit hingga setengah empuk\n4. Tambahkan ikan patin dan irisan tomat\n5. Bumbui dengan garam, asam jawa, dan cabai utuh\n6. Masak dengan api kecil 15 menit\n7. Sajikan pindang hangat dengan nasi putih", 3],
            ['Nasi Kuning Ayam Suwir Urap', 'nasi-kuning-ayam-suwir-urap', 'Nasi kuning harum kunyit dengan ayam suwir dan urap sayur, menu nusantara lengkap.', '4-6 tahun', 4, ['Beras Putih' => 120, 'Daging Ayam' => 60, 'Kangkung' => 20, 'Kelapa Parut' => 20, 'Kacang Panjang' => 20], "1. Masak nasi kuning: beras + santan + kunyit + daun salam\n2. Rebus ayam hingga empuk, suwir-suwir\n3. Tumis ayam suwir dengan sedikit kecap\n4. Rebus kangkung dan kacang panjang, tiriskan\n5. Sangrai kelapa parut, campurkan dengan sayuran rebus\n6. Tata nasi kuning di piring berbentuk tumpeng kecil\n7. Sajikan dengan ayam suwir dan urap sayur", 3],
            ['Sop Ikan Tongkol Sayuran', 'sop-ikan-tongkol-sayuran', 'Sop ikan tongkol segar dengan aneka sayuran, kuah bening hangat berprotein.', '4-6 tahun', 4, ['Ikan Tongkol' => 70, 'Kentang' => 40, 'Wortel' => 25, 'Bayam' => 20, 'Beras Putih' => 120], "1. Potong ikan tongkol per porsi\n2. Kupas kentang dan wortel, potong dadu\n3. Didihkan air, masukkan kentang dan wortel\n4. Setelah 10 menit, masukkan ikan tongkol\n5. Masak 10 menit hingga ikan matang\n6. Tambahkan bayam terakhir, masak 2 menit\n7. Beri garam dan merica\n8. Sajikan sop hangat dengan nasi", 3],
            ['Bebek Goreng Lalapan Sambal', 'bebek-goreng-lalapan-sambal', 'Bebek goreng empuk khas Madura dengan lalapan segar dan sambal.', '4-6 tahun', 4, ['Daging Bebek' => 80, 'Kangkung' => 25, 'Tomat' => 20, 'Beras Putih' => 120], "1. Bersihkan bebek, potong sesuai porsi\n2. Ungkep bebek dengan bumbu rempah hingga empuk\n3. Goreng bebek hingga garing kulit kecokelatan\n4. Rebus kangkung sebentar untuk lalapan\n5. Iris tomat segar\n6. Masak nasi putih\n7. Tata nasi, bebek goreng, dan lalapan\n8. Sajikan dengan sambal ringan", 3],
            ['Pepes Ikan Kembung Kemangi', 'pepes-ikan-kembung-kemangi', 'Pepes ikan kembung harum kemangi dibungkus daun pisang, kaya omega-3.', '4-6 tahun', 4, ['Ikan Kembung' => 80, 'Tomat' => 20, 'Beras Putih' => 120], "1. Bersihkan ikan kembung, buang sisik dan isi perut\n2. Lumuri ikan dengan bumbu kuning dan garam\n3. Iris tomat tipis, siapkan daun kemangi\n4. Layukan daun pisang di atas api\n5. Bungkus ikan dengan tomat dan kemangi dalam daun pisang\n6. Kukus 25 menit hingga matang dan harum\n7. Sajikan pepes dengan nasi putih hangat", 3],
            ['Rendang Daging Sapi Kentang', 'rendang-daging-sapi-kentang', 'Rendang daging sapi khas Minang dengan kentang, protein tinggi dan lezat.', '4-6 tahun', 4, ['Daging Sapi' => 60, 'Kentang' => 50, 'Santan' => 50, 'Beras Putih' => 120], "1. Potong daging sapi dadu besar\n2. Kupas kentang, potong dadu agak besar\n3. Tumis bumbu rendang hingga harum\n4. Masukkan daging, aduk hingga berubah warna\n5. Tuang santan, masak api kecil 1 jam\n6. Setelah daging empuk, masukkan kentang\n7. Masak hingga kuah mengering dan berminyak\n8. Sajikan rendang dengan nasi putih", 3],
            ['Sayur Lodeh Terong Tempe', 'sayur-lodeh-terong-tempe', 'Sayur lodeh terong dan tempe santan, lauk nabati khas Jawa bergizi.', '4-6 tahun', 4, ['Terong' => 40, 'Tempe' => 40, 'Santan' => 40, 'Kacang Panjang' => 25, 'Beras Putih' => 120], "1. Potong terong memanjang, rendam air garam\n2. Potong tempe dadu, goreng sebentar\n3. Potong kacang panjang 3 cm\n4. Didihkan santan encer dengan bumbu lodeh\n5. Masukkan terong dan kacang panjang\n6. Masak 10 menit, tambahkan tempe goreng\n7. Masak 5 menit lagi, koreksi rasa\n8. Sajikan lodeh hangat dengan nasi", 3],
            ['Cah Kangkung Udang Bawang', 'cah-kangkung-udang-bawang', 'Cah kangkung tumis udang ala masakan rumahan, cepat saji dan bergizi.', '4-6 tahun', 4, ['Kangkung' => 50, 'Udang' => 40, 'Beras Putih' => 120], "1. Petik kangkung, potong batang dan daunnya\n2. Kupas udang, buang kepala dan kulit\n3. Iris bawang putih tipis\n4. Panaskan minyak, tumis bawang putih hingga harum\n5. Masukkan udang, tumis hingga berubah warna\n6. Tambahkan kangkung, aduk cepat dengan api besar\n7. Beri sedikit garam dan kecap, masak 3 menit\n8. Sajikan dengan nasi putih", 3],
            ['Soto Betawi Daging Kentang', 'soto-betawi-daging-kentang', 'Soto Betawi dengan daging sapi dan kentang dalam kuah santan gurih.', '4-6 tahun', 4, ['Daging Sapi' => 50, 'Kentang' => 40, 'Santan' => 40, 'Tomat' => 15, 'Beras Putih' => 120], "1. Rebus daging sapi hingga empuk, potong dadu\n2. Kupas kentang, potong dadu, goreng setengah matang\n3. Tumis bumbu soto hingga harum\n4. Masukkan kaldu daging dan santan\n5. Tambahkan kentang goreng dan irisan tomat\n6. Masak hingga mendidih dan kentang empuk\n7. Sajikan soto dengan nasi putih dan pelengkap", 3],
            ['Ikan Bakar Bumbu Rujak Lalapan', 'ikan-bakar-bumbu-rujak-lalapan', 'Ikan bakar bumbu rujak pedas manis dengan lalapan sayur segar.', '4-6 tahun', 4, ['Ikan Nila' => 80, 'Tomat' => 20, 'Kangkung' => 25, 'Beras Putih' => 120], "1. Bersihkan ikan nila, kerat badannya\n2. Haluskan bumbu rujak: cabai, tomat, gula, garam\n3. Lumuri ikan dengan bumbu rujak, marinasi 15 menit\n4. Panggang ikan di atas bara atau teflon\n5. Bolak-balik hingga matang dan bumbu mengering\n6. Siapkan lalapan kangkung rebus\n7. Sajikan dengan nasi putih dan lalapan", 3],
            ['Tumis Cumi Kacang Panjang', 'tumis-cumi-kacang-panjang', 'Tumis cumi-cumi segar dengan kacang panjang kecap, lauk cepat saji.', '4-6 tahun', 4, ['Cumi-Cumi' => 60, 'Kacang Panjang' => 30, 'Beras Putih' => 120], "1. Bersihkan cumi, buang tinta dan tulang rawan\n2. Potong cumi berbentuk cincin\n3. Potong kacang panjang 3 cm\n4. Tumis bawang merah dan bawang putih hingga harum\n5. Masukkan cumi, tumis cepat 2 menit\n6. Tambahkan kacang panjang dan kecap manis\n7. Aduk rata, masak 3 menit api besar\n8. Sajikan dengan nasi putih", 3],
            ['Sayur Kelor Jagung Tahu', 'sayur-kelor-jagung-tahu', 'Sayur bening daun kelor dengan jagung dan tahu, superfood lokal bergizi tinggi.', '4-6 tahun', 4, ['Daun Kelor' => 25, 'Jagung Manis' => 30, 'Tahu' => 30, 'Beras Putih' => 120], "1. Petik daun kelor dari tangkainya\n2. Pipil jagung manis dari tongkol\n3. Potong tahu dadu kecil\n4. Didihkan air, masukkan jagung terlebih dahulu\n5. Setelah 10 menit, masukkan tahu\n6. Tambahkan daun kelor, masak 3 menit saja\n7. Beri garam secukupnya\n8. Sajikan sayur bening hangat dengan nasi", 3],
            ['Semur Daging Telur Kentang', 'semur-daging-telur-kentang', 'Semur daging sapi dengan telur rebus dan kentang, masakan rumahan klasik.', '4-6 tahun', 4, ['Daging Sapi' => 50, 'Telur Ayam' => 50, 'Kentang' => 50, 'Beras Putih' => 120], "1. Potong daging sapi dadu, rebus hingga empuk\n2. Rebus telur, kupas kulitnya\n3. Kupas kentang, potong dadu, goreng sebentar\n4. Tumis bawang merah dan bawang putih\n5. Masukkan daging, tambahkan kecap manis dan air\n6. Masak 15 menit, masukkan telur dan kentang\n7. Masak hingga kuah mengental dan bumbu meresap\n8. Sajikan semur hangat dengan nasi", 3],
            ['Nasi Bakar Isi Ikan Teri Sambal', 'nasi-bakar-isi-ikan-teri-sambal', 'Nasi bakar dalam daun pisang berisi ikan teri sambal, menu praktis dan lezat.', '4-6 tahun', 4, ['Beras Putih' => 120, 'Ikan Teri' => 30, 'Tempe' => 30, 'Tomat' => 15], "1. Masak nasi putih\n2. Goreng ikan teri hingga garing\n3. Cincang tempe, goreng hingga keemasan\n4. Ulek cabai, tomat, garam jadi sambal\n5. Campurkan nasi, ikan teri, tempe, dan sedikit sambal\n6. Bungkus dengan daun pisang, semat lidi\n7. Panggang nasi bakar di atas bara atau teflon\n8. Sajikan hangat", 3],
            ['Sup Kerang Tahu Sayuran', 'sup-kerang-tahu-sayuran', 'Sup kerang segar dengan tahu lembut dan sayuran, kaya mineral dan protein.', '4-6 tahun', 4, ['Kerang' => 50, 'Tahu' => 30, 'Wortel' => 20, 'Bayam' => 15, 'Beras Putih' => 120], "1. Cuci kerang bersih, rendam air garam 30 menit\n2. Potong tahu dadu kecil\n3. Kupas wortel, potong tipis\n4. Didihkan air, masukkan kerang hingga cangkang terbuka\n5. Tambahkan wortel dan tahu, masak 5 menit\n6. Petik bayam, masukkan terakhir\n7. Beri garam dan merica secukupnya\n8. Sajikan sup hangat dengan nasi", 3],
